script:
// Segment — one SegmentedTabs item (ds-metrics §17): takes an equal share of the track; selected = accentPrimary pill
// (radius 20 = 24 − inset) + white text, otherwise el9 text; cross-fades with @motion.smooth (DS accentPill: spring 0.3 s).
// Emits `tap` only when not already selected.
param title: string
param selected: bool = false
event tap
// the theme has no onAccent token: white in both schemes
let onAccent = env.colorScheme == "dark" ? @color.el16 : @color.el1
